  "homepage": "https://github.com/vumichien/claude-code-mods-kit",
  "types": "./types/index.d.ts",
  "userConfig": {
    "testCommands": {
      "type": "string",
      "title": "Your test commands",
      "description": "Comma-separated commands that run your tests, added to the usual runners (pytest, npm test, go test, cargo test and others). Example: ./scripts/check.sh, make ci",
      "default": ""
    },
    "ignore": {
      "type": "string",
      "title": "Not code",
      "description": "Comma-separated file endings whose changes need no test run.",
      "default": ".md,.mdx,.markdown,.txt,.rst,.adoc,.org"
    },
    "band": {
      "type": "string",
      "title": "Band above the prompt",
      "description": "on: the band shows while the mod is on. off: the mod works without a band (Claude still gets its note, and /done-gate answers). /done-gate on and off switch the whole mod, for every session.",
      "default": "on",
      "options": [
        "off",
        "on"
      ]
    }
  }
}

files.types/index.d.ts:
export type Gate = {
  // The last test command that finished in this session.
  lastTest: { passed: boolean; at: number; command: string } | null
  // Code files Claude changed since the last passing test run, relative to the project.
  unchecked: string[]
  // How many times a task was marked done while code was unchecked.
  warnings: number
}

declare module 'claude-code' {
  interface PluginState {
    // enabled: the mod's on/off switch as this session read it from the store, or as /done-gate on|off set it.
    'done-gate': { gate: Gate; enabled: boolean }
  }
}
